modern_c2_q7.program:
def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    man_patches = image_patch.find("man")
    shirt_patches = image_patch.find("shirt")

    if not man_patches or not shirt_patches:
        return image_patch

    man_centers = [(p.left + p.right) / 2 for p in man_patches]
    shirt_centers = [(p.left + p.right) / 2 for p in shirt_patches]

    closest_man = min(man_patches, key=lambda m: abs(shirt_centers[0] - man_centers[man_patches.index(m)]))
    closest_shirt = min(shirt_patches, key=lambda s: abs(shirt_centers[shirt_patches.index(s)] - man_centers[man_patches.index(closest_man)]))

    if closest_shirt.upper < closest_man.lower or closest_shirt.lower > closest_man.upper:
        return closest_man

    return closest_man.crop(max(closest_man.left, closest_shirt.left), max(closest_man.lower, closest_shirt.lower), min(closest_man.right, closest_shirt.right), min(closest_man.upper, closest_shirt.upper))

