    if yellow_and_white_truck.overlaps_with(other_truck.left, other_truck.lower, other_truck.right, other_truck.upper):
        return yellow_and_white_truck

    return yellow_and_white_truck if yellow_and_white_truck.compute_depth() > other_truck.compute_depth() else other_truck

