def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    cars = image_patch.find("car")
    crosswalks = image_patch.find("crosswalk")

    if not cars or not crosswalks:
        return image_patch

    white_cars = [car for car in cars if car.verify_property("car", "white")]

    if not white_cars:
        return image_patch

    crosswalk_rectangles = [(c.left, c.lower, c.right, c.upper) for c in crosswalks]

    def intersects(rect1, rect2):
        return not (rect1[2] < rect2[0] or rect1[0] > rect2[2] or rect1[3] < rect2[1] or rect1[1] > rect2[3])

    white_cars_on_crosswalk = [car for car in white_cars if any(intersects((car.left, car.lower, car.right, car.upper), crosswalk) for crosswalk in crosswalk_rectangles)]

    return white_cars_on_crosswalk[0] if white_cars_on_crosswalk else white_cars[0]

